ANNOUNCE.template:
ANNOUNCE rtsp://{host}:{port}/{path} RTSP/1.0
CSeq: {cseq}
Session: {session_id}
Content-Type: application/sdp
Content-Length: {length}

{sdp_body}

DESCRIBE.template:
DESCRIBE rtsp://{host}:{port}/{path} RTSP/1.0
CSeq: {cseq}
Accept: application/sdp
Session: {session_id}

GET_PARAMETER.template:
GET_PARAMETER rtsp://{host}:{port}/{path} RTSP/1.0
CSeq: {cseq}
Session: {session_id}
Content-Type: text/parameters
Content-Length: {length}

{parameters}

PAUSE.template:
PAUSE rtsp://{host}:{port}/{path} RTSP/1.0
CSeq: {cseq}
Session: {session_id}
Range: {range_spec}

PLAY.template:
PLAY rtsp://{host}:{port}/{path} RTSP/1.0
CSeq: {cseq}
Session: {session_id}
